#!/bin/sh
# fetch_tu117_firmware.sh - the NVIDIA TU117 (GTX 1650 Max-Q) firmware that nouveau (Linux 6.18.21) requests, pinned
# to a linux-firmware release tag plus a sha256 list (plan P0-6, INTERFACES.md v1.1 sections 1.3, 6.2; invariant 16).
#
# Pin: linux-firmware tag 20260916 = commit ab23307cfe7f9366c819025ca3e4778299bc2db2 (2026-09-16).
#   tu117_fw_table.txt (next to this script) = "<name nouveau requests> <real linux-firmware path> <sha256>". It was
#   generated by resolving the WHENCE "Link:" entries (fwtable.py) and is byte-identical for the tag 20260916, the
#   tag 20261019 and commit bf992df7a95b5e19bb8f8546eb4d7c53ab2598d0 (main on 2026-10-23, the table's first source),
#   checked on the builder on 2026-10-25: nvidia/tu117/gsp is a directory link to tu116/gsp, whose bootloader-* and
#   gsp-* link to tu102/gsp; tu117 acr/*, sec2/*, nvdec/scrubber.bin and gr/{fecs,gpccs}_bl.bin link to tu116. Names =
#   the 30 nvidia/tu117/* entries of "modinfo -F firmware nouveau.ko" (acr/tu102.c, gr/tu102.c, sec2/tu102.c,
#   fb/tu102.c nvdec/scrubber, gsp/tu116.c NVKM_GSP_FIRMWARE_BOOTER(tu117, 535.113.01|570.144)).
#   The sha256 column equals ../firmware_staged_sha256.txt (same 30 files, the paths nouveau requests).
#
# Modes (POSIX sh + curl + sha256sum; Git Bash on Windows or the builder):
#   sh fetch_tu117_firmware.sh [STAGED_DIR] [OUT_DIR]
#     verify the staged firmware against the table and download ONLY missing or mismatching files into a NEW dir
#     (OUT_DIR, default this script's dir; files land in OUT_DIR/nvidia/..). STAGED_DIR is only read.
#     defaults: STAGED_DIR=/c/GB-x86/inject/native/firmware. env CHECK_ONLY=1: report only, download nothing.
#   sh fetch_tu117_firmware.sh --licence [OUT_DIR]
#     download WHENCE and LICENSES/LICENCE.nvidia at the pinned tag, check their sha256, write OUT_DIR/LICENCE.nvidia
#     and OUT_DIR/WHENCE.tu117 (whence_tu117.py, python3 -I) and check the excerpt's sha256 too (default OUT_DIR: this
#     script's dir, where both files are kept for the payload, INTERFACES 6.2).
#
# Needed at runtime (nouveau 6.18 nvkm/subdev/gsp/tu116.c tu116_gsps[] = 570.144, then 535.113.01, then no-GSP):
#   GSP-RM (default, NvGspRm=1): gsp/{booter_load,booter_unload,bootloader,gsp}-570.144.bin is enough;
#     the 535.113.01 set is the fallback (gb.nouveau.fw=535).
#   Legacy (nouveau.config=NvGspRm=0): acr/*, gr/*, sec2/*, nvdec/scrubber.bin (~0.3 MB).
set -u
HERE=$(cd "$(dirname "$0")" && pwd)
TABLE=$HERE/tu117_fw_table.txt
TAG=20260916
COMMIT=ab23307cfe7f9366c819025ca3e4778299bc2db2
BASE="https://git.kernel.org/pub/scm/linux/kernel/git/firmware/linux-firmware.git/plain"
REF="h=refs/tags/$TAG"
WHENCE_SHA=9350832c1e9afc35df50fa8b9793b31d60d78ef963152eec903fc0dbc6b4a559
LICENCE_SHA=bc5225a57f49c5249dcf238e4ae6437811677a2a8a7f579c3d839e058653ee44
EXCERPT_SHA=5de89a22c3ff211fdd8d21062770cbf238b4cfb4125fb3df2df0763a3af9b73a
[ -f "$TABLE" ] || { echo "missing $TABLE"; exit 2; }

sha() { sha256sum "$1" | cut -d' ' -f1; }

if [ "${1:-}" = --licence ]; then
  OUT=${2:-$HERE}
  T=$(mktemp -d) || exit 1
  trap 'rm -rf "$T"' EXIT
  curl -fsSL --retry 3 -o "$T/WHENCE" "$BASE/WHENCE?$REF" || { echo "FETCH FAILED WHENCE"; exit 1; }
  curl -fsSL --retry 3 -o "$T/LICENCE.nvidia" "$BASE/LICENSES/LICENCE.nvidia?$REF" || { echo "FETCH FAILED LICENCE.nvidia"; exit 1; }
  [ "$(sha "$T/WHENCE")" = "$WHENCE_SHA" ] || { echo "WHENCE sha256 mismatch (tag $TAG moved?)"; exit 1; }
  [ "$(sha "$T/LICENCE.nvidia")" = "$LICENCE_SHA" ] || { echo "LICENCE.nvidia sha256 mismatch"; exit 1; }
  cut -d' ' -f1 "$TABLE" > "$T/names.txt"
  python3 -I "$HERE/whence_tu117.py" "$T/WHENCE" "$T/names.txt" \
    "linux-firmware tag $TAG (commit $COMMIT), https://git.kernel.org/pub/scm/linux/kernel/git/firmware/linux-firmware.git" \
    > "$T/WHENCE.tu117" || { echo "whence_tu117.py failed"; exit 1; }
  [ "$(sha "$T/WHENCE.tu117")" = "$EXCERPT_SHA" ] || { echo "WHENCE.tu117 sha256 differs from the pinned excerpt"; exit 1; }
  mkdir -p "$OUT"
  cp "$T/WHENCE.tu117" "$T/LICENCE.nvidia" "$OUT/" || exit 1
  echo "licence: $OUT/WHENCE.tu117 ($EXCERPT_SHA), $OUT/LICENCE.nvidia ($LICENCE_SHA) from tag $TAG"
  exit 0
fi

STAGED=${1:-/c/GB-x86/inject/native/firmware}
OUT=${2:-$HERE}
case "$(cd "$OUT" 2>/dev/null && pwd)" in "$(cd "$STAGED" 2>/dev/null && pwd)") echo "OUT must differ from STAGED"; exit 2;; esac

n_ok=0; n_need=0; n_got=0; n_fail=0
while read -r name src want; do
  [ -n "$name" ] || continue
  have=""
  [ -f "$STAGED/$name" ] && have=$(sha "$STAGED/$name")
  if [ "$have" = "$want" ]; then echo "ok       $name"; n_ok=$((n_ok+1)); continue; fi
  n_need=$((n_need+1))
  if [ -n "$have" ]; then echo "MISMATCH $name (staged sha256 $have)"; else echo "MISSING  $name"; fi
  [ "${CHECK_ONLY:-0}" = 1 ] && continue
  dst="$OUT/$name"; mkdir -p "$(dirname "$dst")"
  if [ -f "$dst" ] && [ "$(sha "$dst")" = "$want" ]; then
    echo "         already in $dst"; n_got=$((n_got+1)); continue
  fi
  if curl -fsSL --retry 3 -o "$dst.part" "$BASE/$src?$REF" && [ "$(sha "$dst.part")" = "$want" ]; then
    mv "$dst.part" "$dst"; echo "         fetched $src -> $dst"; n_got=$((n_got+1))
  else
    rm -f "$dst.part"; echo "         FETCH FAILED (or sha256 mismatch) for $src"; n_fail=$((n_fail+1))
  fi
done < "$TABLE"
echo "summary (tag $TAG): $n_ok ok in $STAGED, $n_need missing/mismatching, $n_got now in $OUT, $n_fail failed (staged dir untouched)"
[ "$n_fail" = 0 ]
